/**
 * بترندر الأيقونة سواء كانت اسم ('tent') أو SVG كامل ('<svg...')
 */
function renderIcon($value, $size = 30, $stroke = 2): string {
    if (!$value) return '';
    if (str_starts_with(trim($value), '<')) return $value;

    $paths = getIconPaths();
    $path  = $paths[$value] ?? $paths['sparkles'];

    return '<svg viewBox="0 0 24 24" width="'.$size.'" height="'.$size.'" fill="none" stroke="currentColor" stroke-width="'.$stroke.'" stroke-linecap="round" stroke-linejoin="round">'.$path.'</svg>';
}